const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');

const htmlPath = path.resolve(process.cwd(), 'index.html');
const axePath = require.resolve('axe-core/axe.min.js');

function summarize(label, result) {
  return {
    label,
    violations: result.violations
      .filter((violation) => !violation.tags.includes('best-practice'))
      .map((violation) => ({
        id: violation.id,
        impact: violation.impact,
        targets: violation.nodes.map((node) => node.target)
      }))
  };
}

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.setContent(fs.readFileSync(htmlPath, 'utf8'), { waitUntil: 'load' });
  await page.addScriptTag({ path: axePath });

  const initial = await page.evaluate(async () => window.axe.run(document));
  await page.getByRole('button', { name: 'Send request' }).click();
  const invalidSubmit = await page.evaluate(async () => window.axe.run(document));
  await browser.close();

  const summaries = [summarize('initial', initial), summarize('invalid-submit', invalidSubmit)];
  console.log(JSON.stringify(summaries, null, 2));

  if (summaries.some((summary) => summary.violations.length > 0)) {
    process.exit(1);
  }
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
